content.text:
{
  "name": "事件信号组件",
  "name_en": "Psygnal-based Signal Component",
  "manufacturer": "",
  "description": "一个基于 psygnal 的非物理软件组件，用于实验控制软件中的事件通知与回调分发。它可在界面、线程或其他模块之间连接函数、断开连接并发射信号，以传递状态变化或触发后续处理，而不直接控制具体实验硬件。",
  "description_en": "A non-physical software component based on psygnal for event notification and callback dispatch in laboratory control software. It is used to connect functions, disconnect them, and emit signals between UI elements, threads, or other modules to propagate state changes or trigger follow-up processing, without directly controlling any laboratory hardware.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "将回调函数连接到该信号。",
      "description_en": "Connect a callback function to the signal."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开该信号与一个或全部回调函数的连接。",
      "description_en": "Disconnect one callback or all callbacks from the signal."
    },
    {
      "action_name": "auto-emit",
      "description": "发射该信号并向已连接的回调传递参数。",
      "description_en": "Emit the signal and pass arguments to connected callbacks."
    },
    {
      "action_name": "types",
      "description": "获取信号参数类型。",
      "description_en": "Get the signal argument types."
    },
    {
      "action_name": "info",
      "description": "获取信号信息。",
      "description_en": "Get the signal information."
    }
  ],
  "tag_hints": [
    "event signaling",
    "callback connection",
    "software helper",
    "psygnal",
    "inter-module communication",
    "thread/UI notifications"
  ]
}

